"import json\nimport re\n\ntranscript_path = \"/Users/issam/.gemini/antigravity-ide/brain/1a560cd2-9a41-4bb1-a0fc-06e5a057a0a6/.system_generated/logs/transcript.jsonl\"\n\nreconstructed_lines = {}\n\n# Match lines like \"1234: some code\"\nline_pattern = re.compile(r\"^(\\d+):\\s(.*)$\")\n\nwith open(transcript_path, \"r\", encoding=\"utf-8\") as f:\n    for line in f:\n        try:\n            data = json.loads(line)\n            content = data.get(\"content\", \"\")\n            if \"pipeline.py\" in content and \"Total Lines\" in content:\n                # Split content into lines and find code lines\n                lines = content.split(\"\\n\")\n                for l in lines:\n                    match = line_pattern.match(l.strip())\n                    if match:\n                        line_num = int(match.group(1))\n                        line_code = match.group(2)\n                        reconstructed_lines[line_num] = line_code\n        except Exception as e:\n            pass\n\nprint(f\"Reconstructed {len(reconstructed_lines)} lines.\")\nif reconstructed_lines:\n    max_line = max(reconstructed_lines.keys())\n    print(f\"Max line number: {max_line}\")\n    # Write to file\n    with open(\"reconstructed_pipeline.py\", \"w\", encoding=\"utf-8\") as out:\n        for i in range(1, max_line + 1):\n            out.write(reconstructed_lines.get(i, f\"# MISSING LINE {i}\\n\") + \"\\n\")\n    print(\"Saved to reconstructed_pipeline.py\")\n"